const $=s=>document.querySelector(s);
const paths={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',discover:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7Z',chat:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-3 2v-9.5A8.5 8.5 0 0 1 9.5 4h3a8.5 8.5 0 0 1 8.5 7.5Z',level:'M4 20h16M6 15h2v5H6v-5Zm5-5h2v10h-2V10Zm5-5h2v15h-2V5Z',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',lock:'M5 10h14v11H5V10Zm3 0V6a4 4 0 0 1 8 0v4m-4 5v2',filter:'M4 7h16M7 3v8M4 17h16m-7-4v8',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',arrow:'M5 12h14m-6-6 6 6-6 6',photo:'M3 4h18v16H3V4Zm0 12 6-6 4 4 3-3 5 5M17 8h.01',video:'M3 5h12v14H3V5Zm12 5 6-4v12l-6-4',voice:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0V4ZM5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8',check:'m5 12 4 4L19 6',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Zm-4 10 3 3 5-6',close:'m6 6 12 12M6 18 18 6',plus:'M12 5v14M5 12h14',exit:'M9 3H4v18h5m4-14 5 5-5 5m-5-5h14'};
const icon=n=>`<span class="ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${paths[n]||paths.discover}"/></svg></span>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photo=()=>'/demo/portraits.jpg';
const sprite=p=>p.demo?'class="demo-image" style="--col:'+p.demoIndex%3+';--row:'+Math.floor(p.demoIndex/3)+'"':'';
const examples=[['Анастасия',26,'Москва',8,'За маленькие путешествия, большие завтраки и людей с чувством юмора.',['Путешествия','Кофе','Искусство']],['Мария',24,'Санкт-Петербург',5,'Коллекционирую красивые места и поводы выключить телефон.',['Архитектура','Кино','Прогулки']],['Александра',27,'Казань',7,'Могу рассказать о последней книге. А лучше — послушаю тебя.',['Книги','Музыка','Горы']],['Виктория',25,'Москва',9,'В выходные меня можно найти у воды. Или в поисках новых впечатлений.',['Море','Фотография','Йога']],['Александр',29,'Санкт-Петербург',6,'Готовлю пасту, хожу в горы и всё ещё верю в случайные встречи.',['Кулинария','Горы','Музыка']],['Михаил',28,'Москва',8,'Ищу человека, с которым даже обычный вторник станет интереснее.',['Спорт','Кофе','Кино']]].map((a,i)=>({id:'demo-'+i,name:a[0],age:a[1],city:a[2],level:a[3],bio:a[4],interests:a[5],intent:'Знакомства и общение',demo:true,demoIndex:i,media:[{id:'d'+i,basic:true,min:1,url:photo(i),locked:false},{id:'x'+i,min:4,locked:true},{id:'y'+i,min:8,locked:true}],liked:false}));
const interests=['Путешествия','Кофе','Кино','Музыка','Книги','Спорт','Искусство','Прогулки','Кулинария','Горы','Море','Технологии','Фотография','Йога','Игры','Танцы'];
const state={page:'discover',me:null,profiles:[],matches:[],demo:false,tab:'all',filter:{city:'',minAge:18,maxAge:100},loading:true,error:null,chat:null,chatTimer:null,telegramFlow:null,account:null,miniToken:null};
let toastTimer;
const deckState={dismissed:new Set(),history:[],busy:false};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
async function api(path,options={}){let body=options.body;if(getMiniApp()&&body&&!(body instanceof FormData)&&['auth/login','auth/register','auth/password'].includes(path))body={...body,transport:'miniapp'};const headers={...(body instanceof FormData?{}:{'Content-Type':'application/json'}),...(state.miniToken?{Authorization:'Bearer '+state.miniToken}:{})};const res=await fetch('/api/'+path,{...options,headers,body:body instanceof FormData?body:body?JSON.stringify(body):undefined});const data=await res.json();if(!res.ok){const e=new Error(data.error||'Ошибка запроса');e.status=res.status;throw e;}if(data.sessionToken&&getMiniApp())state.miniToken=data.sessionToken;return data;}
let refreshFlight=null,celebrationTimer=null;const levelCelebrations=[];
function scheduleCelebration(){clearTimeout(celebrationTimer);if(!levelCelebrations.length)return;celebrationTimer=setTimeout(()=>{if(!state.me){levelCelebrations.length=0;return;}if($('.modal')||document.visibilityState==='hidden'){scheduleCelebration();return;}const item=levelCelebrations.shift();modal('Поздравляем!',`<div class="level-celebration"><div class="celebration-number">${item.level}</div><h3>У тебя уровень ${item.level}</h3><p>Задание выполнено: ${esc(item.label)}.</p>${item.level===4?'<p>Теперь доступна остальная галерея — с учётом порога, выбранного автором.</p>':''}<button class="primary wide" data-action="celebration-next">Продолжить</button></div>`);},700);}
async function refreshMe(){if(refreshFlight)return refreshFlight;refreshFlight=(async()=>{let me=await api('me');state.account=await api('auth/session');for(let i=0;i<9;i++){const task=me.tasks?.find(t=>t.canClaim);if(!task)break;await api('progress',{method:'POST',body:{key:task.key}});const next=await api('me');if(next.level<=me.level)break;levelCelebrations.push({level:task.targetLevel,label:task.label});me=next;}state.me=me;scheduleCelebration();})();try{return await refreshFlight;}finally{refreshFlight=null;}}
function modal(title,body,large=false){closeModal();$('#overlay').innerHTML=protectedHTML(`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="modal-close" aria-label="Закрыть" data-action="close">×</button></div>${body}</section></div>`);document.body.style.overflow='hidden';$('.modal-close').focus();hydrateImages();syncMiniBack();}
function closeModal(){clearChatRecording();scheduleCelebration();state.telegramFlow=null;clearInterval(state.chatTimer);state.chatTimer=null;state.chat=null;$('#overlay').innerHTML='';document.body.style.overflow='';hydrateImages();syncMiniBack();}
function brand(mobile=false){return `<a href="#" class="brand ${mobile?'mobile-brand':''}" data-action="nav" data-page="discover" aria-label="LoveLevel — знакомства"><span class="brand-icon">${icon('heart')}</span><span>love<em>level</em></span>${!mobile?'<span class="beta">BETA</span>':''}</a>`;}
function nextUnlock(lvl){return lvl<4?'Дополнительные фотографии':'Фотографии с более высоким порогом доступа';}
function rail(){
 if(state.me?.railHidden&&state.page!=='level')return '';
 const current=state.me?.level||1,next=state.me?.tasks?.find(t=>t.targetLevel===current+1);
 return `<aside class="rail" aria-label="Уровень и доступ"><section class="panel level-panel"><div class="level-card-label"><span>Мой уровень</span><span class="level-card-controls"><span class="level-card-scale">LOVELEVEL / 10</span>${state.me?`<button class="rail-toggle" data-action="rail-toggle" aria-label="${state.me.railHidden?'Показывать панель уровней':'Скрыть панель уровней'}" title="${state.me.railHidden?'Показывать на всех экранах':'Скрыть, оставив в разделе Мой уровень'}">${icon(state.me.railHidden?'plus':'close')}</button>`:''}</span></div><div class="level-top"><div class="level-number"><strong>${String(current).padStart(2,'0')}</strong><span>${current<4?'Базовый доступ':'Расширенный доступ'}</span></div><span class="level-seal">${icon('level')}</span></div><div class="level-progress-block"><div class="progress-copy"><span>Достигнутый уровень</span><strong>${current}<span> / 10</span></strong></div><div class="progress" role="progressbar" aria-label="Прогресс уровней" aria-valuenow="${current}" aria-valuemin="1" aria-valuemax="10"><i style="width:${(current-1)/9*100}%"></i></div></div><div class="level-next"><span>${current===10?'Все уровни получены':`Следующий — уровень ${current+1}`}</span><strong>${next?.ready?'Готов к получению':''}</strong></div><button class="level-card-action" data-action="nav" data-page="level">${current===10?'Мои достижения':'Условия повышения'} ${icon('arrow')}</button></section><section class="panel unlocks-panel"><div class="panel-title"><h3>Что дают уровни</h3><span class="muted">01—10</span></div><div class="unlock-item is-open"><span class="unlock-icon">${icon('photo')}</span><div><p>Основное + 2 фото</p><small>Уровни 1–3</small></div></div><div class="unlock-item ${current>=4?'is-open':''}"><span class="unlock-icon">${icon('photo')}</span><div><p>Остальная галерея</p><small>С уровня 4 · с учётом порога автора</small></div></div><div class="unlock-item"><span class="unlock-icon">${icon('video')}</span><div><p>Видео и голосовые</p><small>Доступ по уровню, выбранному автором</small></div></div><p class="rail-note">Все анкеты видны сразу. Загрузка своих материалов доступна на любом уровне.</p></section></aside>`;
}
function shell(content){
 const profile=state.me?.profile;
 const nav=[['discover','discover','Знакомства','Знакомства'],['matches','heart','Симпатии','Симпатии'],['chats','chat','Сообщения','Сообщения'],['level','level','Мой уровень','Уровень'],['profile','user','Мой профиль','Профиль']];
 const pageNames={discover:'Знакомства',matches:'Взаимные симпатии',chats:'Сообщения',level:'Мой уровень',profile:'Мой профиль',admin:'Модерация'};
 return `<div class="shell page-${esc(state.page)}"><aside class="sidebar">${brand()}<div class="nav-label">Приложение</div><nav class="nav" aria-label="Навигация">${nav.map(([page,i,label,mobile])=>`<button class="${state.page===page?'active':''}" data-action="nav" data-page="${page}" aria-label="${label}" ${state.page===page?'aria-current="page"':''}>${icon(i)}<span class="nav-desktop">${label}</span><span class="nav-mobile" aria-hidden="true">${mobile}</span></button>`).join('')}${state.me?.admin?`<button class="admin-nav ${state.page==='admin'?'active':''}" data-action="nav" data-page="admin">${icon('shield')}<span>Модерация</span></button>`:''}</nav>
  <div class="sidebar-note"><div class="sidebar-note-title">${icon('lock')}<span>Доступ по уровню</span></div><p>Больше материалов по мере заполнения профиля.</p><button class="text-button" data-action="help">Правила уровней ${icon('arrow')}</button></div>
  <button class="side-user" data-action="${profile?'nav':'setup'}" ${profile?'data-page="profile"':''}><span class="avatar">${esc(profile?.name?.[0]||'L')}</span><span><strong>${esc(profile?.name||'Создать профиль')}</strong><small>${profile?'Уровень '+(state.me?.level||1):'Начать знакомство'}</small></span>${icon('arrow')}</button>
 </aside><main class="main"><header class="topbar"><div class="crumb"><span>LoveLevel</span><span class="crumb-slash">/</span><strong>${pageNames[state.page]||'Аккаунт'}</strong></div>${brand(true)}<div class="top-right"><span class="test-pill"><span class="status-dot"></span>Тест · 18+</span><button class="tiny-link help-link" data-action="help">Как это работает</button>${state.me?.admin?`<button class="mobile-admin" aria-label="Модерация" title="Модерация" data-action="nav" data-page="admin">${icon('shield')}</button>`:''}${state.me?'<button class="tiny-link session-link" data-action="logout">Выйти</button>':'<button class="tiny-link session-link" data-action="auth-login">Войти</button>'}</div></header>${content}<footer class="footer"><span>© 2026 LoveLevel</span><div><button data-action="legal">Правила и приватность</button><span>·</span><button data-action="support">Поддержка</button></div></footer></main></div>`;
}
function heading(title,sub,section=''){return `<div class="heading"><div>${section?`<div class="eyebrow">${esc(section)}</div>`:''}<h1>${title}</h1><p>${sub}</p></div><button class="text-button heading-help" data-action="help">Как работают уровни ${icon('arrow')}</button></div>`;}
function emptyState({kind='discover',title,description,actions}){return `<div class="empty empty-${kind}"><div class="empty-symbol">${icon(kind==='messages'?'chat':kind==='matches'?'heart':'discover')}</div><span class="empty-label">${kind==='discover'?'Результаты поиска':kind==='matches'?'Взаимный интерес':'Переписка'}</span><h2>${title}</h2><p>${description}</p><div class="empty-actions">${actions}</div></div>`;}
function personCard(p){const image=p.media.find(m=>m.url&&(!m.kind||m.kind==='photo'))?.url;return `<article class="person"><div class="portrait" data-action="person" data-id="${esc(p.id)}" tabindex="0" role="button" aria-label="Открыть анкету ${esc(p.name)}">${image?`<img ${sprite(p)} src="${esc(image)}" alt="${esc(p.name)}" loading="lazy" referrerpolicy="no-referrer">`:'<div class="photo-pending">'+icon('photo')+'<span>Фото пока недоступно</span></div>'}<span class="level-badge">Уровень ${p.level}</span>${p.demo?'<span class="verified">ДЕМО</span>':''}<div class="portrait-indicator" aria-hidden="true"><i></i><i></i><i></i></div></div><div class="person-info"><div class="person-heading"><h3>${esc(p.name)}<span>, ${p.age}</span></h3></div><div class="city">${icon('pin')}${esc(p.city)}</div><p class="person-bio">${esc(p.bio||'Описание пока не добавлено.')}</p><div class="chips">${p.interests.slice(0,3).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="person-footer"><span class="access-note">${icon(p.media.some(m=>m.locked)?'lock':'photo')}${p.media.some(m=>m.locked)?'Есть закрытые материалы':'Доступные фотографии'}</span><button class="like ${p.liked?'liked':''}" data-action="like" data-id="${esc(p.id)}" aria-label="${p.liked?'Симпатия отправлена':'Нравится '+esc(p.name)}">${icon('heart')}</button></div></div></article>`;}
function discover(){
 const demo=state.demo||!state.me?.profile;let list=demo?examples:state.profiles;
 if(state.tab==='liked')list=list.filter(p=>p.liked);
 if(state.filter.city)list=list.filter(p=>p.city.toLowerCase().includes(state.filter.city.toLowerCase()));
 list=list.filter(p=>p.age>=state.filter.minAge&&p.age<=state.filter.maxAge);
 const liked=state.tab==='liked';
 if(!liked)list=list.filter(p=>!deckState.dismissed.has(p.id)&&!p.liked);
 return heading('Знакомства','Анкеты, фотографии и люди с общими интересами.','Люди')+`<div class="workspace"><section class="discovery">
 ${demo?`<div class="demo-notice"><span><strong>Демо-режим</strong> Вымышленные анкеты для знакомства с интерфейсом.</span><button class="text-button" data-action="${state.me?.profile?'real':'setup'}">${state.me?.profile?'К участникам':'Создать анкету'} ${icon('arrow')}</button></div>`:''}
 ${state.error?`<div class="demo-notice error-notice" role="alert"><span>${esc(state.error)}</span><button data-action="retry" class="text-button">Повторить</button></div>`:''}
 <div class="toolbar"><div class="tabs" aria-label="Список анкет"><button class="${!liked?'selected':''}" data-action="tab" data-tab="all" aria-pressed="${!liked}">Все анкеты</button><button class="${liked?'selected':''}" data-action="tab" data-tab="liked" aria-pressed="${liked}">Мои симпатии</button></div><button class="filter-button" data-action="filters">${icon('filter')}Фильтры${state.filter.city?'<span class="filter-dot"></span>':''}</button></div>
 <div class="result-count"><span>${state.filter.city?esc(state.filter.city):'Все города'}</span><span class="count-separator">·</span><span>${demo?'Демонстрационные анкеты':list.length+' анкет'}</span><span class="result-age">${state.filter.minAge}–${state.filter.maxAge} лет</span></div>
 ${state.loading?'<div class="loading">Загрузка анкет</div>':list.length?`${liked?`<div class="cards">${list.map(personCard).join('')}</div>`:discoverStack(list)}`:emptyState({title:liked?'Нет отправленных симпатий':'Нет подходящих анкет',description:liked?'Отмеченные анкеты появятся здесь. Начните с просмотра людей в разделе знакомств.':'Расширьте возрастной диапазон или выберите все города, чтобы увидеть больше анкет.',actions:liked?'<button class="primary" data-action="tab" data-tab="all">Смотреть анкеты '+icon('arrow')+'</button>':'<button class="primary" data-action="filters">Изменить фильтры '+icon('arrow')+'</button><button class="secondary" data-action="demo">Посмотреть демо</button>'})}
 ${!liked&&deckState.history.length&&!list.length?'<button class="secondary" data-action="deck-rewind">Вернуть пропущенную анкету</button>':''}<div class="discovery-note">${icon('lock')}<span>Все анкеты доступны сразу. Уровень открывает дополнительные материалы.</span></div>
 </section>${rail()}</div>`;
}
function discoverStack(list){return `<div class="discover-stage"><div class="discover-stack" aria-label="Анкеты для знакомства">${list.slice(0,3).map((p,i)=>`<div class="deck-card ${i===0?'deck-active':''}" data-deck-id="${esc(p.id)}" style="--depth:${i}" ${i?'inert aria-hidden="true"':''}>${personCard(p)}${!i?'<span class="swipe-label swipe-yes">Нравится</span><span class="swipe-label swipe-no">Пропустить</span>':''}</div>`).reverse().join('')}</div><div class="deck-actions"><button class="deck-rewind" data-action="deck-rewind" aria-label="Вернуть пропущенную анкету" ${!deckState.history.length?'disabled':''}>↶</button><button class="deck-pass" data-action="deck-pass" aria-label="Пропустить анкету">${icon('close')}</button><button class="deck-like" data-action="deck-like" aria-label="Поставить симпатию">${icon('heart')}</button></div><p class="deck-hint">← Пропустить <span>→ Нравится</span><span>Z Вернуть пропущенную</span></p><div class="deck-announcement" role="status" aria-live="polite"></div></div>`;}
function rewindDeck(){if(deckState.busy)return;const id=deckState.history.pop();if(!id){toast('Нет пропущенных анкет для возврата');return;}deckState.dismissed.delete(id);render();}
async function swipeDeck(direction){const card=$('.deck-active');if(!card||deckState.busy)return;const id=card.dataset.deckId,p=findPerson(id);if(direction>0&&!p?.demo&&!state.me?.profile){setup();return;}deckState.busy=true;try{if(direction>0&&!p?.demo){await like(id);}const active=$('.deck-active');if(active?.dataset.deckId===id){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;await active.animate([{transform:getComputedStyle(active).transform},{transform:`translateX(${direction*700}px) rotate(${direction*22}deg)`,opacity:0}],{duration:reduced?0:260,easing:'cubic-bezier(.2,.7,.3,1)',fill:'forwards'}).finished;}deckState.dismissed.add(id);if(direction<0)deckState.history.push(id);render();if(p?.demo&&direction>0)toast('Демо: симпатия не отправляется');}catch(e){toast(e.message);const active=$('.deck-active');if(active){active.style.transform='';active.style.removeProperty('--drag');}}finally{deckState.busy=false;}}
let deckDrag=null,deckSuppressClick=false;
document.addEventListener('pointerdown',e=>{const card=e.target.closest('.deck-active');if(!card||e.button!==0||deckState.busy||e.target.closest('button,a,input,video,audio'))return;deckDrag={card,id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0,dragged:false};});
document.addEventListener('pointermove',e=>{const d=deckDrag;if(!d||d.id!==e.pointerId)return;d.dx=e.clientX-d.x;d.dy=e.clientY-d.y;if(!d.dragged){if(Math.abs(d.dy)>Math.abs(d.dx)&&Math.abs(d.dy)>10){deckDrag=null;return;}if(Math.abs(d.dx)<8)return;d.dragged=true;d.card.setPointerCapture(e.pointerId);d.card.classList.add('is-dragging');}d.card.style.transform=`translate(${d.dx}px,${d.dy*.12}px) rotate(${d.dx/24}deg)`;d.card.style.setProperty('--drag',Math.min(1,Math.abs(d.dx)/100));d.card.dataset.direction=d.dx>0?'yes':'no';});
function finishDeckDrag(e,cancel=false){const d=deckDrag;if(!d||d.id!==e.pointerId)return;deckDrag=null;d.card.classList.remove('is-dragging');if(!d.dragged)return;deckSuppressClick=true;setTimeout(()=>deckSuppressClick=false,0);if(!cancel&&Math.abs(d.dx)>Math.min(120,d.card.offsetWidth*.27))swipeDeck(Math.sign(d.dx));else{d.card.style.transform='';d.card.style.removeProperty('--drag');}}
document.addEventListener('pointerup',e=>finishDeckDrag(e));document.addEventListener('pointercancel',e=>finishDeckDrag(e,true));
document.addEventListener('click',e=>{if(deckSuppressClick){e.preventDefault();e.stopImmediatePropagation();}},true);
document.addEventListener('dragstart',e=>{if(e.target.closest('.deck-card'))e.preventDefault();});
document.addEventListener('keydown',e=>{if(state.page!=='discover'||state.tab!=='all'||$('.modal')||e.repeat||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;if(['ArrowLeft','ArrowRight','z','Z','Backspace'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')swipeDeck(-1);else if(e.key==='ArrowRight')swipeDeck(1);else rewindDeck();}});
function levelJourney(me,current){const next=me?.tasks?.find(t=>t.targetLevel===current+1);return `<div class="level-journey" style="--journey-progress:${(current-1)/9*100}%"><ol class="journey-track" aria-label="Путь по уровням">${Array.from({length:10},(_,i)=>{const n=i+1;return `<li class="journey-step ${n<current?'is-complete':n===current?'is-current':'is-future'}" ${n===current?'aria-current="step"':''} aria-label="Уровень ${n}${n===current?', текущий':''}"><span class="journey-index" aria-hidden="true">${String(n).padStart(2,'0')}</span><span class="journey-marker" aria-hidden="true">${n<current?icon('check'):n===current?String(n).padStart(2,'0'):''}</span></li>`;}).join('')}</ol><div class="journey-caption"><strong>Уровень ${current}</strong><span>${current<4?'Базовый доступ':'Расширенный доступ'}</span></div><div class="journey-next">${icon(current===10?'check':'arrow')}<span>${current===10?'Максимальный уровень достигнут':esc(next?.label||'Создай профиль для повышения уровня')}<small>${current===10?'Уровень сохраняется':esc(next?.hint||'Все инструменты доступны заранее')}</small></span></div></div>`;}
const taskTools={basics:{label:'Заполнить профиль',target:'#name'},description:{label:'Заполнить описание',target:'#bio'},photos:{label:'Добавить фото',target:'#upload-form'},like:{label:'Смотреть анкеты'},days:{label:'Как считаются дни'},privacy:{label:'Настроить доступ',target:'.gallery-section'},video:{label:'Добавить видео',target:'#video-upload-form'},voice:{label:'Добавить голосовое',target:'#voice-upload-form'}};
const taskAction=key=>taskTools[key]?.label||'Выполнить';
function taskContext(){const task=state.me?.tasks?.find(t=>t.tool===state.taskGoal);if(!task)return '';return `<div class="task-context"><div><strong>${task.ready?'Условие выполнено':esc(task.label)}</strong><p>${task.ready?'Условие учтено. Уровень повысится автоматически, когда выполнены предыдущие задания.':esc(task.hint)}</p></div><button class="secondary" data-action="nav" data-page="level">К уровням ${icon('arrow')}</button></div>`;}
function focusTask(){const selector=taskTools[state.taskGoal]?.target;if(!selector)return;requestAnimationFrame(()=>{const target=$(selector);target?.scrollIntoView({block:'center',behavior:'instant'});if(target?.matches('input,select,textarea,button'))target.focus({preventScroll:true});});}
async function openTask(key){if(!taskTools[key])return;if(key==='like'){await navigate('discover');return;}if(key==='days'){modal('Дни использования',`<p>Засчитано разных дней: <strong>${state.me?.days||0}</strong>.</p><p>День считается автоматически при входе в приложение. Повторные открытия в тот же день не увеличивают счётчик. Дни считаются по Москве, не обязательно подряд. Пропуск ничего не обнуляет.</p><button class="primary wide" data-action="close">Понятно</button>`);return;}state.taskGoal=key;if(!state.me){setup();return;}state.page='profile';closeModal();render();const photo=key==='privacy'?state.me?.profile?.media.find(m=>m.kind==='photo'&&!m.basic):null;if(photo)editMedia(photo.id);else focusTask();}
function levels(){const me=state.me,current=me?.level||1;return heading('Мой уровень','Выполняй условия заранее. Дни не обязательно подряд.','Доступ')+`<div class="workspace"><div class="primary-column"><section class="section-card tasks-section"><div class="section-heading"><div><h2>Условия уровней</h2><p>Действия учитываются заранее. Уровни повышаются автоматически по порядку и сохраняются после перерыва.</p></div><span class="section-counter">${current} / 10</span></div><div class="task task-complete"><div class="milestone-number">01</div><div class="task-description"><h3>Зарегистрироваться</h3><p>${me?'Выполнено':'Создай аккаунт'}</p></div>${me?'<span class="task-status">'+icon('check')+'</span>':'<button class="primary" data-action="setup">Регистрация</button>'}</div>${(me?.tasks||[]).map(task=>`<div class="task ${task.claimed?'task-complete':''}"><div class="milestone-number">${String(task.targetLevel).padStart(2,'0')}</div><div class="task-description"><h3>${esc(task.label)}</h3><p>${task.claimed?'Уровень получен':task.ready?task.canClaim?'Условие выполнено':'Выполнено заранее · сначала получи уровень '+(task.targetLevel-1):esc(task.hint)}</p></div>${task.claimed?'<span class="task-status">'+icon('check')+'</span>':task.canClaim?'<span class="task-ahead">Условие выполнено</span>':task.ready?'<span class="task-ahead">Учтено</span>':`<button class="secondary" data-action="task-tool" data-key="${task.tool}">${taskAction(task.tool)}</button>`}</div>`).join('')}<p class="small-note milestone-note">Все инструменты доступны с первого уровня. Видео — до 30 секунд, голосовое — до 30 секунд. Взаимность для задания с симпатией не нужна.</p></section><section class="section-card"><div class="section-heading"><div><h2>Шкала уровней</h2><p>Твой статус и следующий шаг.</p></div><span class="section-counter">01—10</span></div>${levelJourney(me,current)}<div class="level-explainer"><div><strong>01–03</strong><span>Основное фото и до двух дополнительных</span></div><div><strong>04–10</strong><span>Остальные фото с порогом не выше твоего уровня</span></div></div><p class="small-note">Для видео и голосовых автор выбирает минимальный уровень зрителя. Запрашивать открытие не нужно.</p></section></div>${rail()}</div>`;}

function profileForm(){const p=state.me?.profile;const today=new Date();today.setFullYear(today.getFullYear()-18);return heading(p?'Мой профиль':'Создать профиль','Информация, которую увидят другие участники.','Аккаунт')+`<div class="workspace"><div class="primary-column">${taskContext()}<section class="section-card profile-editor"><div class="profile-summary"><span class="profile-avatar">${esc(p?.name?.[0]||'L')}</span><div><h2>${esc(p?.name||'Основная информация')}</h2><p>${p?esc(p.city)+' · Уровень '+(state.me?.level||1):'Профиль для знакомств'}</p></div><span class="profile-status">${p?.paused?'Скрыт из поиска':p?'В поиске':'Новый профиль'}</span></div><form id="profile-form"><div class="form-grid"><div class="field"><label for="name">Имя</label><input id="name" name="name" maxlength="40" required value="${esc(p?.name||'')}" placeholder="Имя в анкете"></div><div class="field">${p?`<label for="profile-age">Возраст</label><input id="profile-age" value="${p.age} лет" readonly><small>Дата рождения скрыта от других участников.</small>`:`<label for="birthdate">Дата рождения</label><input id="birthdate" name="birthdate" type="date" max="${today.toISOString().slice(0,10)}" required><small>Только для участников от 18 лет.</small>`}</div><div class="field"><label for="city">Город</label><input id="city" name="city" maxlength="60" required value="${esc(p?.city||'')}" placeholder="Например, Москва"></div><div class="field"><label for="gender">Пол</label><select id="gender" name="gender">${[['woman','Женщина'],['man','Мужчина'],['other','Другой вариант']].map(([v,t])=>`<option value="${v}" ${p?.gender===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="seeking">Кого ищу</label><select id="seeking" name="seeking">${[['all','Со всеми'],['woman','С женщинами'],['man','С мужчинами']].map(([v,t])=>`<option value="${v}" ${p?.seeking===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="intent">Цель знакомства</label><select id="intent" name="intent">${['Серьёзные отношения','Знакомства и общение','Пока разбираюсь'].map(t=>`<option ${p?.intent===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field full"><label for="bio">О себе</label><textarea id="bio" name="bio" maxlength="700" placeholder="Интересы, занятия и то, что важно в знакомстве.">${esc(p?.bio||'')}</textarea><small id="bio-count">${(p?.bio||'').trim().length} / 60 символов для задания</small></div><div class="field full"><label>Интересы · до 8</label><div class="interest-options">${interests.map(t=>`<button type="button" data-action="interest" data-interest="${esc(t)}" class="${p?.interests.includes(t)?'on':''}">${t}</button>`).join('')}</div></div></div><label class="check"><input type="checkbox" name="adult" required ${p?'checked':''}>Мне исполнилось 18 лет, я указываю достоверные данные.</label><label class="check"><input type="checkbox" name="terms" required ${p?'checked':''}><span>Принимаю <button type="button" class="text-button" style="display:inline;padding:0" data-action="legal">правила и условия приватности</button> закрытого теста.</span></label><div class="actions"><button type="submit" class="primary">${p?'Сохранить изменения':'Создать анкету'} ${icon('arrow')}</button><span class="small-note">Уровень не продаётся</span></div></form></section>${p?telegramSettings()+galleryManager(p):''}${p?`<section class="section-card"><h2>Настройки аккаунта</h2><p>${p.paused?'Анкета сейчас скрыта из поиска.':'Пауза скрывает анкету из поиска. Уровень и переписка сохраняются.'}</p><div class="actions"><button class="secondary" data-action="pause">${p.paused?'Вернуться в поиск':'Приостановить анкету'}</button><button class="secondary" data-action="blocks">Блокировки</button>${state.account?.passwordAvailable?'<button class="secondary" data-action="password">Сменить пароль</button>':''}<button class="text-button danger" data-action="delete-account">Удалить аккаунт</button></div></section>`:''}</div>${rail()}</div>`;}
function mediaElement(m,url=m.url,alt='Материал профиля'){if(!url)return '';if(m.kind==='video'||m.mime?.startsWith('video/'))return `<video src="${esc(url)}" controls playsinline preload="metadata" controlslist="nodownload" aria-label="Видео профиля"></video>`;if(m.kind==='voice'||m.mime?.startsWith('audio/'))return `<div class="voice-material">${icon('voice')}<audio src="${esc(url)}" controls preload="metadata" controlslist="nodownload" aria-label="Голосовое профиля"></audio></div>`;return `<img src="${esc(url)}" alt="${esc(alt)}">`;}
function accessSelect(name='min'){return `<select name="${name}">${Array.from({length:10},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}</select>`;}
function galleryManager(p){const photos=p.media.filter(m=>!m.kind||m.kind==='photo'),videos=p.media.filter(m=>m.kind==='video'),voices=p.media.filter(m=>m.kind==='voice');return `<section class="section-card gallery-section"><div class="section-heading"><div><h2>Моя галерея</h2><p>Все форматы можно добавлять заранее. Материалы публикуются после проверки.</p></div></div><div class="gallery">${p.media.map(m=>`<div class="gallery-item ${m.kind&&m.kind!=='photo'?'clip-item':''}">${mediaElement(m,m.url,'Моя фотография')}<button data-action="edit-media" data-id="${esc(m.id)}" aria-label="Настроить материал">⋯</button><div class="label">${m.kind==='video'?'Видео · ':m.kind==='voice'?'Голосовое · ':m.basic?'Основное · ':''}${m.status==='pending'?'На проверке':m.status==='rejected'?'Отклонено':'Уровень '+m.min+'+'}</div></div>`).join('')}</div><form id="upload-form" class="upload-box"><div class="upload-heading">${icon('photo')}<div><h3>Добавить фотографию</h3><p>${photos.length} из 12 · JPEG, PNG, WebP · до 5 МБ</p></div></div><div class="field"><label for="file">Выбрать фотографию</label><input type="file" id="file" name="file" accept="image/jpeg,image/png,image/webp" required></div><div class="actions"><div class="field"><label for="photo-min">Доступ с уровня</label>${accessSelect().replace('<select ','<select id="photo-min" ')}</div><button class="primary" type="submit" ${photos.length>=12?'disabled':''}>Загрузить фото ${icon('plus')}</button></div></form><form id="video-upload-form" class="upload-box"><div class="upload-heading">${icon('video')}<div><h3>Добавить короткое видео</h3><p>${videos.length} из 2 · MP4, MOV или WebM · до 30 секунд · исходник до 50 МБ</p></div></div><div class="field"><label for="video-file">Выбрать видео</label><input type="file" id="video-file" name="file" accept="video/mp4,video/webm,video/quicktime" required></div><div id="video-preview" class="clip-preview"></div><div class="actions"><div class="field"><label for="video-min">Доступ с уровня</label>${accessSelect().replace('<select ','<select id="video-min" ')}</div><button class="primary" type="submit" ${videos.length>=2?'disabled':''}>Загрузить видео</button></div></form><form id="voice-upload-form" class="upload-box"><div class="upload-heading">${icon('voice')}<div><h3>Добавить голосовое</h3><p>${voices.length} из 2 · до 30 секунд · исходник до 50 МБ</p></div></div><div class="record-controls"><button class="secondary" type="button" data-action="record-voice">${icon('voice')} Записать голос</button><span id="record-status" role="status">Или выбери готовую аудиозапись</span></div><div id="voice-preview" class="clip-preview"></div><div class="field"><label for="voice-file">Аудиозапись</label><input type="file" id="voice-file" name="file" accept="audio/webm,audio/ogg,audio/mp4,audio/x-m4a,audio/wav,audio/mpeg"></div><div class="actions"><div class="field"><label for="voice-min">Доступ с уровня</label>${accessSelect().replace('<select ','<select id="voice-min" ')}</div><button class="primary" type="submit" ${voices.length>=2?'disabled':''}>Загрузить голосовое</button></div></form><p class="upload-policy">Видео автоматически сжимается до 720p и 3 МБ, аудио — до 192 КБ. Исходник не сохраняется. Только собственные материалы. Откровенные материалы в тестовой версии запрещены. Запись с микрофона требует HTTPS и разрешения браузера; если запись недоступна, можно загрузить готовый файл.</p></section>`;}

function matchPage(chats=false){const title=chats?'Сообщения':'Взаимные симпатии',description=chats?'Личные разговоры после взаимного интереса.':'Участники, которым вы тоже понравились.';return heading(title,description,'Общение')+`<div class="workspace"><section class="section-card matches-section ${state.matches.length?'has-matches':'is-empty'}">${state.matches.length?`<div class="list-heading"><span>${chats?'Переписки':'Совпадения'}</span><span>${state.matches.length}</span></div>${state.matches.map(p=>`<button class="match-row" data-action="chat" data-id="${esc(p.id)}"><span class="avatar">${p.media.find(m=>m.url&&(!m.kind||m.kind==='photo'))?`<img src="${esc(p.media.find(m=>m.url&&(!m.kind||m.kind==='photo')).url)}" alt="">`:esc(p.name[0])}</span><span class="match-details"><span class="match-name">${esc(p.name)}, ${p.age}<span class="chip">Уровень ${p.level}</span></span><span class="match-preview">${esc(p.last?.body||'Начать переписку')}</span></span>${icon('arrow')}</button>`).join('')}`:emptyState({kind:chats?'messages':'matches',title:chats?'Нет сообщений':'Пока нет взаимных симпатий',description:chats?'Переписка появится после взаимного лайка.':'Отмечайте интересные анкеты. Когда симпатия взаимная, здесь появится совпадение.',actions:'<button class="primary" data-action="nav" data-page="discover">Смотреть анкеты '+icon('arrow')+'</button>'})}</section>${rail()}</div>`;}
async function render(){let body=state.page==='discover'?discover():state.page==='level'?levels():state.page==='profile'?profileForm():state.page==='admin'?heading('Модерация','Проверка фотографий и жалоб участников.','Управление')+'<div id="admin-content" class="section-card"><div class="loading">Загружаем очередь</div></div>':matchPage(state.page==='chats');$('#app').innerHTML=protectedHTML(shell(body));hydrateImages();syncMiniBack();if(state.page==='profile'&&voiceDraft)updateVoicePreview();if(state.page==='admin')loadAdmin();}
async function loadDiscover(){if(state.me?.profile){const q=new URLSearchParams(state.filter);state.profiles=(await api('discover?'+q)).profiles;}}
async function navigate(page){if(page==='profile'&&!state.me){setup();return;}state.page=page;if(page!=='profile'){state.taskGoal=null;clearVoice();}closeModal();window.scrollTo({top:0,behavior:'instant'});if(['matches','chats'].includes(page)){if(!state.me?.profile){setup();return;}try{state.matches=(await api('matches')).matches;}catch(e){toast(e.message);}}if(page==='level')try{await refreshMe();}catch(e){toast(e.message);}if(page==='discover')try{await loadDiscover();}catch(e){state.error=e.message;}render();}
function setup(){if(!state.me){if(getMiniApp())showMiniWelcome();else authDialog('login');return;}state.page='profile';state.demo=false;closeModal();render();}
async function authDialog(mode='login'){
 let config;try{config=await api('auth/config');}catch(e){toast(e.message);return;}
 const register=mode==='register';
 modal(register?'Создать аккаунт':'Вход в LoveLevel',`<div class="welcome">${config.telegram?.enabled?'<button class="telegram-button wide" data-action="telegram-login">Войти через Telegram</button><div class="auth-divider"><span>или по email</span></div>':''}<p>${register?'Регистрация в LoveLevel. Доступно участникам от 18 лет.':'Email и пароль вашего аккаунта.'}</p><form id="auth-form" data-mode="${register?'register':'login'}"><div class="field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" maxlength="254" autocomplete="email" required placeholder="you@example.com"></div><div class="spacer"></div><div class="field"><label for="auth-password">Пароль</label><input id="auth-password" name="password" type="password" minlength="${register?10:1}" maxlength="128" autocomplete="${register?'new-password':'current-password'}" required>${register?'<small>Не менее 10 символов. Сохрани пароль в менеджере паролей.</small>':''}</div>${register&&config.inviteRequired?'<div class="spacer"></div><div class="field"><label for="auth-invite">Код приглашения</label><input id="auth-invite" name="invite" required autocomplete="off"></div>':''}${register?'<label class="check"><input type="checkbox" name="adult" required>Мне исполнилось 18 лет.</label><label class="check"><input type="checkbox" name="terms" required><span>Принимаю <button type="button" class="text-button" style="display:inline;padding:0" data-action="legal">правила и условия приватности</button>.</span></label>':''}<div class="actions"><button class="primary wide" type="submit">${register?'Создать аккаунт':'Войти'} ${icon('arrow')}</button></div></form><div class="actions">${register?'<button class="text-button" data-action="auth-login">Уже есть аккаунт? Войти</button>':config.registration?'<button class="text-button" data-action="auth-register">Первый раз? Создать аккаунт</button>':'<p>Сейчас вход доступен приглашённым участникам теста.</p>'}</div>${!register?'<div class="spacer"></div><button class="tiny-link" data-action="support">Не получается войти?</button>':''}</div>`);
}

const levelConditions=['Зарегистрироваться','Заполнить основные данные и цель знакомства','Написать о себе от 60 символов и выбрать 3 интереса','Добавить 3 фотографии','Поставить 1 симпатию — взаимность не нужна','Пользоваться приложением в 2 разных дня','Сохранить доступ для дополнительного фото','Пользоваться приложением в 4 разных дня','Добавить видео до 30 секунд','Добавить голосовое до 30 секунд'];
function conditionsHTML(){return `<ol class="conditions-list">${levelConditions.map((text,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(text)}</p></li>`).join('')}</ol>`;}
function help(){modal('Уровни и условия',`<p class="help-lead">Все анкеты видны сразу. Уровень открывает материалы с соответствующим порогом доступа.</p>${conditionsHTML()}<div class="help-rules"><p><strong>Можно выполнить заранее.</strong> Загрузка видео, запись голоса и другие инструменты доступны с первого уровня. Получай уровни по порядку в разделе «Мой уровень».</p><p><strong>Дни не обязательно подряд.</strong> Счётчик увеличивается автоматически при входе в новый календарный день по Москве. Пропуски не обнуляют прогресс.</p><p><strong>Что видно:</strong> на уровнях 1–3 — основное фото и до двух дополнительных. С 4-го — остальная фотогалерея с учётом порога автора. Для видео и голосовых автор выбирает минимальный уровень. Например, «8+» открывается на восьмом уровне без запроса.</p><p>Уровни, текстовая переписка и голосовые до 30 секунд бесплатны. Отправка видеокружочков до 10 секунд доступна в Plus; просмотр бесплатен. Оплата пока не подключена. Уровень не продаётся и не снижается после перерыва.</p></div><button class="primary wide" data-action="close">Понятно</button>`,true);}

function legal(){modal('Правила и приватность',`<div class="legal-copy"><p>Закрытый технический тест LoveLevel · версия от 30 октября 2026 года.</p><h3>Кто может участвовать</h3><p>Только совершеннолетние пользователи от 18 лет. Указывайте свою дату рождения и размещайте только собственные фото, видео и голосовые. В текущем тесте запрещены обнажение, сексуально откровенные материалы, реклама, угрозы, мошенничество и публикации без согласия изображённых людей.</p><h3>Голосовые и видеосообщения</h3><p>В переписке после взаимной симпатии доступны голосовые до 30 секунд бесплатно и видеокружочки до 10 секунд для отправителей с Plus. Просмотр бесплатен. До 20 видеокружочков за 24 часа. Получатель может отключить приём видео в переписке. Записи сжимаются, исходники не сохраняются. Сообщения доступны участникам переписки; модератор может открыть конкретную запись из жалобы, просмотр фиксируется. Это не сквозное шифрование. При удалении аккаунта его переписки и записи удаляются. На запись можно пожаловаться и заблокировать отправителя. Задания уровней с видео и голосом выполняются публикациями в профиле, а не сообщениями.</p><h3>Условия получения уровней</h3>${conditionsHTML()}<p>Действия выполняются заранее, уровни получаются по порядку. Учитываются только собственные материалы, не отклонённые модератором. Разные дни использования считаются по Москве автоматически, включая день регистрации, не обязательно подряд. Повторное открытие приложения в тот же день не увеличивает счётчик. Уровни сохраняются после перерыва и удаления материала; нарушения рассматриваются модерацией отдельно. Ранее достигнутый уровень при обновлении шкалы не снижается. Платных уровней и ускорений нет.</p><h3>Кто видит данные</h3><p>Имя, возраст, город, описание и интересы видны участникам. Дата рождения не показывается. Доступ к фото, видео и голосовым определяется уровнем зрителя и порогом материала. Основное фото доступно всем участникам. Два обычных дополнительных фото выбираются стабильно для каждого зрителя.</p><h3>Модерация</h3><p>Загруженные фото, видео и голосовые проверяются до публикации. При жалобе уполномоченный модератор может прочитать переданное сообщение. Доступ модератора фиксируется. Переписка не использует сквозное шифрование. Не передавайте банковские данные, документы и другую чувствительную информацию.</p><h3>Хранение и удаление</h3><p>Видео до 30 секунд сжимается до 720p, 24 кадров/с и 3 МБ; аудио до 30 секунд — до 192 КБ. Исходник до 50 МБ используется временно только для обработки и удаляется. Сохраняется сжатая версия без исходных метаданных. </p><p>Анкеты, прогресс, симпатии и переписка сохраняются в серверной базе; фото, видео и голосовые — в закрытом файловом хранилище. Можно приостановить анкету или удалить аккаунт в настройках профиля. При удалении стираются анкета, все материалы, прогресс, лайки и переписка. Жалобы и журнал модерации могут сохраняться для расследования нарушений; сроки и данные оператора должны быть утверждены до публичного запуска.</p><h3>Копирование</h3><p>Встроенного скачивания чужих фотографий нет. Полностью предотвратить скриншоты или съёмку другим устройством невозможно.</p><h3>Поддержка</h3><p>Во время закрытого теста связь с организатором — через канал, в котором вы получили приглашение. До открытого запуска здесь появятся реквизиты оператора, контакт поддержки и окончательные документы для выбранных стран.</p></div>`,true);}
function filters(){modal('Кто тебе интересен?',`<form id="filters-form"><div class="form-grid"><div class="field full"><label for="filter-city">Город</label><input id="filter-city" name="city" placeholder="Оставь пустым — все города" value="${esc(state.filter.city)}"><small>География всегда бесплатна.</small></div><div class="field"><label for="age-min">Возраст от</label><input id="age-min" type="number" min="18" max="100" name="minAge" value="${state.filter.minAge}" required></div><div class="field"><label for="age-max">До</label><input id="age-max" type="number" min="18" max="100" name="maxAge" value="${state.filter.maxAge}" required></div></div><div class="actions"><button class="primary">Показать анкеты</button><button type="button" class="secondary" data-action="reset-filters">Сбросить</button></div></form>`);}
function findPerson(id){return [...examples,...state.profiles,...state.matches].find(p=>p.id===id);}
function person(id){const p=findPerson(id);if(!p)return;const image=p.media.find(m=>m.url&&(!m.kind||m.kind==='photo'))?.url;modal(p.name,`${p.demo?'<div class="demo-notice">Вымышленная анкета для знакомства с интерфейсом.</div>':''}${image?`<div class="profile-cover"><img ${sprite(p)} src="${esc(image)}" alt="${esc(p.name)}" referrerpolicy="no-referrer"></div>`:''}<div class="detail-head"><h2>${esc(p.name)}, ${p.age}</h2><span class="level-badge">${icon('level')} LV ${p.level}</span></div><div class="detail-sub">${esc(p.city)} · ${esc(p.intent)}</div><p>${esc(p.bio)}</p><div class="chips">${p.interests.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div><div class="gallery">${p.media.map(m=>`<div class="gallery-item ${m.kind&&m.kind!=='photo'?'clip-item':''}">${m.locked?`<div class="locked">${icon('lock')}<strong>С уровня ${m.kind==='photo'&&m.min===1?4:m.min}</strong><span>Закрытый материал</span></div>`:p.demo?`<img ${sprite(p)} src="${esc(m.url)}" alt="Фотография ${esc(p.name)}">`:mediaElement(m)}</div>`).join('')}</div><div class="actions"><button class="primary" data-action="${p.matched?'chat':'like'}" data-id="${esc(id)}">${icon('heart')}${p.matched?'Написать':p.liked?'Симпатия отправлена':'Мне нравится'}</button>${!p.demo?`<button class="secondary" data-action="report" data-id="${esc(id)}">Пожаловаться</button><button class="text-button danger" data-action="block" data-id="${esc(id)}">Заблокировать</button>`:''}</div>`,true);}
async function like(id){const p=findPerson(id);if(p?.demo){toast('Это пример анкеты. Для настоящих знакомств создай профиль.');return;}if(!state.me?.profile){setup();return;}if(p?.liked){toast('Симпатия уже отправлена');return;}const r=await api('like',{method:'POST',body:{target:id}});await refreshMe();for(const x of [...state.profiles,...state.matches])if(x.id===id){x.liked=true;x.matched=r.matched;}if(r.matched){modal('Взаимная симпатия',`<div class="welcome-heart">${icon('heart')}</div><p>${esc(p.name)} тоже отметил вашу анкету. Можно начать переписку.</p><button class="primary wide" data-action="chat" data-id="${esc(id)}">Написать сообщение ${icon('arrow')}</button>`);}else{toast('Симпатия отправлена');if($('#overlay').innerHTML)person(id);}render();}
function chatPlayer(m,url='/api/chat-media/'+m.id){return `<div class="chat-attachment">${m.mime.startsWith('video/')?`<video class="chat-circle" controls playsinline preload="metadata" data-auth-image="${esc(url)}" aria-label="Видеокружочек"></video>`:`<audio controls preload="metadata" data-auth-image="${esc(url)}" aria-label="Голосовое сообщение"></audio>`}<span class="clip-duration">${Math.ceil(m.duration||0)} с</span></div>`;}
const chatRecording={generation:0,recorder:null,stream:null,timer:null,draft:null,url:null,kind:null,target:null};
function clearChatRecording(){chatRecording.generation++;clearInterval(chatRecording.timer);chatRecording.timer=null;const recorder=chatRecording.recorder;chatRecording.recorder=null;if(recorder?.state==='recording')recorder.stop();chatRecording.stream?.getTracks().forEach(t=>t.stop());chatRecording.stream=null;chatRecording.draft=null;if(chatRecording.url)URL.revokeObjectURL(chatRecording.url);chatRecording.url=null;chatRecording.target=null;const submit=$('#chat-media-form [type=submit]');if(submit)submit.hidden=true;const host=$('#chat-recording');if(host)host.innerHTML='';}
function previewChat(file,kind){if(chatRecording.url)URL.revokeObjectURL(chatRecording.url);chatRecording.draft=file;chatRecording.kind=kind;chatRecording.target=state.chat;chatRecording.url=URL.createObjectURL(file);const submit=$('#chat-media-form [type=submit]');if(submit)submit.hidden=false;const host=$('#chat-media-preview');if(host)host.innerHTML=`${kind==='video'?`<video class="chat-circle" controls playsinline src="${chatRecording.url}"></video>`:`<audio controls src="${chatRecording.url}"></audio>`}<button type="button" class="text-button" data-action="chat-discard">Удалить запись</button>`;}
async function recordChat(kind){
 if(chatRecording.recorder?.state==='recording'){chatRecording.recorder.stop();return;}
 if(kind==='video'&&!state.me?.plus){toast('Видеокружочки входят в LoveLevel Plus. Оплата пока не подключена.');return;}
 if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Браузер не поддерживает запись. Можно выбрать готовый файл.');return;}
 clearChatRecording();const generation=chatRecording.generation,target=state.chat,limit=kind==='video'?10:30;
 $('#chat-media-preview').innerHTML='';$('#chat-media-file').value='';$('#chat-media-kind').value=kind;
 try{const stream=await navigator.mediaDevices.getUserMedia({audio:true,...(kind==='video'?{video:{facingMode:'user',width:{ideal:480},height:{ideal:480}}}:{})});if(chatRecording.generation!==generation||state.chat!==target){stream.getTracks().forEach(t=>t.stop());return;}chatRecording.stream=stream;chatRecording.target=target;
 const formats=kind==='video'?['video/webm;codecs=vp8,opus','video/mp4','video/webm']:['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'];const mime=formats.find(t=>MediaRecorder.isTypeSupported(t));const recorder=new MediaRecorder(stream,{...(mime?{mimeType:mime}:{}),...(kind==='video'?{videoBitsPerSecond:700000,audioBitsPerSecond:32000}:{audioBitsPerSecond:32000})});chatRecording.recorder=recorder;const parts=[];recorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data);};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(chatRecording.generation!==generation)return;clearInterval(chatRecording.timer);chatRecording.timer=null;chatRecording.recorder=null;chatRecording.stream=null;const blob=new Blob(parts,{type:recorder.mimeType||mime});if(blob.size&&state.chat===target){previewChat(new File([blob],kind==='video'?'circle.webm':'voice.webm',{type:blob.type.split(';')[0]}),kind);$('#chat-recording').textContent='Запись готова. Проверь перед отправкой.';}};recorder.onerror=()=>{if(chatRecording.generation!==generation)return;clearChatRecording();toast('Не удалось записать. Попробуй выбрать файл.');};
 $('#chat-recording').innerHTML=`${kind==='video'?'<video class="chat-circle chat-live" autoplay muted playsinline></video>':''}<span class="chat-record-clock">Запись · 0 / ${limit} с</span><button class="secondary" data-action="chat-record" data-kind="${kind}">Остановить</button>`;const live=$('.chat-live');if(live)live.srcObject=stream;const started=Date.now();recorder.start(200);chatRecording.timer=setInterval(()=>{const elapsed=Math.floor((Date.now()-started)/1000);const label=$('.chat-record-clock');if(label)label.textContent=`Запись · ${Math.min(elapsed,limit)} / ${limit} с`;if(elapsed>=limit&&recorder.state==='recording')recorder.stop();},100);
 }catch(e){if(chatRecording.generation!==generation)return;clearChatRecording();toast(e.name==='NotAllowedError'?'Разреши доступ к микрофону'+(kind==='video'?' и камере':'')+' или выбери готовый файл.':'Не удалось начать запись. Можно выбрать готовый файл.');}
}
async function sendChatRecording(form){if(chatRecording.recorder?.state==='recording')throw new Error('Сначала останови запись');const target=form.dataset.target;if(state.chat!==target)throw new Error('Переписка закрыта');const file=chatRecording.draft,kind=chatRecording.kind;if(!file||chatRecording.target!==target)throw new Error('Запиши или выбери файл');if(kind==='video'&&!state.me.plus)throw new Error('Отправка видео доступна в LoveLevel Plus');const data=new FormData();let normalized=file;if(kind==='voice'){const type={'video/webm':'audio/webm','video/mp4':'audio/mp4','audio/x-m4a':'audio/mp4','audio/x-wav':'audio/wav'}[file.type];if(type)normalized=new File([file],file.name,{type});}data.set('file',normalized);const button=form.querySelector('[type=submit]');button.textContent='Сжимаем и отправляем…';try{await api('chat-upload?'+new URLSearchParams({target,kind}),{method:'POST',body:data});if(state.chat===target){clearChatRecording();form.reset();$('#chat-media-preview').innerHTML='';await loadChat(true);}}finally{if(button.isConnected)button.textContent='Отправить запись';}}
document.addEventListener('change',async e=>{try{if(e.target.id==='chat-receive-video'){const checked=e.target.checked;try{await api('chat-settings',{method:'PATCH',body:{receiveVideo:checked}});state.me.receiveVideo=checked;}catch(error){e.target.checked=!checked;throw error;}}if(e.target.id==='chat-media-kind'){clearChatRecording();$('#chat-media-preview').innerHTML='';$('#chat-media-file').value='';}if(e.target.id==='chat-media-file'){const file=e.target.files?.[0],kind=$('#chat-media-kind').value;clearChatRecording();$('#chat-media-preview').innerHTML='';if(!file)return;if(file.size>50*1024*1024)throw new Error('Выбери файл до 50 МБ');if(kind==='video'&&!state.me.plus)throw new Error('Отправка видео доступна в LoveLevel Plus');previewChat(file,kind);}}catch(error){toast(error.message);}});
window.addEventListener('pagehide',clearChatRecording);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&chatRecording.recorder?.state==='recording')chatRecording.recorder.stop();});
async function chat(id){const p=findPerson(id);if(!p)return;modal('Вы и '+p.name,`<button class="text-button" data-action="person" data-id="${esc(id)}">Открыть анкету</button><div id="chat-messages" class="message-list"><div class="loading">Загружаем разговор</div></div><form id="chat-form" class="chat-compose"><input name="body" maxlength="2000" placeholder="Сообщение…" required autocomplete="off"><button class="primary" aria-label="Отправить">${icon('arrow')}</button></form><div class="chat-media-tools"><button class="secondary" data-action="chat-record" data-kind="voice">${icon('voice')} Голосовое · 30 с</button><button class="secondary" data-action="chat-record" data-kind="video">${icon('video')} Кружочек · 10 с ${state.me?.plus?'':' · Plus'}</button></div><div id="chat-recording" aria-live="polite"></div><form id="chat-media-form" data-target="${esc(id)}"><details class="chat-file-picker"><summary>Выбрать готовую запись</summary><div class="chat-file-tools"><label for="chat-media-file">Файл записи</label><select id="chat-media-kind" name="kind" aria-label="Тип записи"><option value="voice">Голосовое · 30 секунд</option><option value="video">Видео · 10 секунд · Plus</option></select><input id="chat-media-file" type="file" name="file" accept="audio/*,video/mp4,video/webm,video/quicktime"></div></details><div id="chat-media-preview"></div><button class="primary" type="submit" hidden>Отправить запись</button><p class="small-note">Сначала предпросмотр. Голосовые бесплатны, отправка видео — Plus. Получатель смотрит бесплатно.</p></form><label class="check chat-video-setting"><input type="checkbox" id="chat-receive-video" ${state.me.receiveVideo?'checked':''}>Принимать видеосообщения</label><div class="actions"><button class="tiny-link" data-action="report" data-id="${esc(id)}">Пожаловаться</button><button class="tiny-link danger" data-action="block" data-id="${esc(id)}">Заблокировать</button></div>`);state.chat=id;await loadChat(true);state.chatTimer=setInterval(()=>{if(document.visibilityState==='visible')loadChat(false).catch(()=>{});},5000);}
async function loadChat(scroll){if(!state.chat)return;const id=state.chat;const r=await api('chat/'+encodeURIComponent(id));if(state.chat!==id||!$('#chat-messages'))return;const container=$('#chat-messages'),near=container.scrollHeight-container.scrollTop-container.clientHeight<80;const signature=JSON.stringify(r.messages);if(container.dataset.signature===signature)return;container.dataset.signature=signature;const existing=new Map([...container.querySelectorAll('[data-message-id]')].map(el=>[el.dataset.messageId,el]));const template=document.createElement('template');template.innerHTML=r.messages.length?r.messages.map(m=>`<div data-message-id="${esc(m.id)}" class="bubble ${m.sender===state.me.id?'mine':''}">${m.mime?chatPlayer(m):esc(m.body)}<small>${new Date(m.created).toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'})}${m.sender!==state.me.id?` · <button class="tiny-link" data-action="report" data-id="${esc(id)}" data-message="${esc(m.id)}">Пожаловаться</button>`:''}</small></div>`).join(''):'<p>Начните переписку.</p>';const children=[...template.content.children].map(el=>existing.get(el.dataset.messageId)||el);for(let i=0;i<children.length;i++){if(container.children[i]!==children[i])container.insertBefore(children[i],container.children[i]||null);}while(container.children.length>children.length)container.lastElementChild.remove();hydrateImages();if(scroll||near)container.scrollTop=container.scrollHeight;}
function report(id,message){modal('Сообщить о нарушении',`<p>Модератор получит жалобу${message?' и выбранное сообщение':''}. Не отправляйте сюда лишние персональные данные.</p><form id="report-form" data-target="${esc(id)}" data-message="${esc(message||'')}"><div class="field"><label for="reason">Что произошло?</label><textarea id="reason" name="reason" required maxlength="1000" placeholder="Фейк, давление, оскорбление или другая причина"></textarea></div><div class="actions"><button class="primary">Отправить жалобу</button></div></form>`);}
function editMedia(id){const m=state.me.profile.media.find(x=>x.id===id);if(!m)return;modal('Настройки материала',`<form id="media-form" data-id="${esc(id)}"><div class="field"><label for="media-min">Доступ с уровня</label><select id="media-min" name="min" ${m.basic?'disabled':''}>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${m.min===i+1?'selected':''}>${i+1}</option>`).join('')}</select></div>${!m.basic&&m.kind==='photo'?'<label class="check"><input type="checkbox" name="basic">Сделать основным фото</label>':m.basic?'<p>Основное фото доступно всем. Для задания выбери дополнительное фото.</p>':''}<div class="actions"><button class="primary" type="submit">Сохранить доступ</button><button type="button" class="text-button danger" data-action="delete-media" data-id="${esc(id)}">Удалить материал</button></div></form>`);}
async function loadAdmin(){try{const r=await api('admin/queue');if(!$('#admin-content'))return;$('#admin-content').innerHTML=protectedHTML(`<h2>Материалы · ${r.media.length}</h2>${r.media.length?r.media.map(m=>`<div class="admin-item">${mediaElement(m,'/api/admin/photo?id='+encodeURIComponent(m.id),'На проверке')}<p>${esc(m.name)} · с уровня ${m.min}</p><div class="actions"><button class="primary" data-action="review" data-id="${esc(m.id)}" data-status="approved">Одобрить</button><button class="secondary danger" data-action="review" data-id="${esc(m.id)}" data-status="rejected">Отклонить</button></div></div>`).join(''):'<p>Очередь пуста.</p>'}<div class="spacer"></div><h2>Жалобы · ${r.reports.length}</h2>${r.reports.map(r=>`<div class="admin-item"><p>${esc(r.reason)}</p><small>${esc(r.created)}</small><div class="actions">${r.message?`<button class="secondary" data-action="report-context" data-id="${esc(r.id)}">Посмотреть сообщение</button>`:''}<button class="secondary" data-action="resolve-report" data-id="${esc(r.id)}">Закрыть жалобу</button></div></div>`).join('')}`);hydrateImages();}catch(e){if($('#admin-content'))$('#admin-content').textContent=e.message;}}
async function claim(){await refreshMe();await loadDiscover();render();}
